437	    public void handleFieldSecurity(ResteasyReactiveResourceMethodEntriesBuildItem resourceMethodEntries,
438	            JaxRsResourceIndexBuildItem index,
439	            BuildProducer<ResourceMethodCustomSerializationBuildItem> producer) {
440	        IndexView indexView = index.getIndexView();
441	        boolean noSecureFieldDetected = indexView.getAnnotations(SECURE_FIELD).isEmpty();
442	        if (noSecureFieldDetected) {
443	            return;
444	        }
445	
446	        Map<String, Boolean> typeToHasSecureField = new HashMap<>(getTypesWithSecureField());
447	        List<ResourceMethodCustomSerializationBuildItem> result = new ArrayList<>();
448	        for (ResteasyReactiveResourceMethodEntriesBuildItem.Entry entry : resourceMethodEntries.getEntries()) {
449	            MethodInfo methodInfo = entry.getMethodInfo();
450	            if (methodInfo.hasAnnotation(DISABLE_SECURE_SERIALIZATION)) {
451	                continue;
452	            }
453	            if (entry.getActualClassInfo().declaredAnnotation(DISABLE_SECURE_SERIALIZATION) != null) {
454	                if (!methodInfo.hasAnnotation(ENABLE_SECURE_SERIALIZATION)) {
455	                    continue;
456	                }
457	            }
458	
459	            ResourceMethod resourceInfo = entry.getResourceMethod();
460	            boolean isJsonResponse = false;
461	            if (resourceInfo.getProduces() != null) {
462	                for (String produces : resourceInfo.getProduces()) {
463	                    if (produces.toLowerCase(Locale.ROOT).contains(MediaType.APPLICATION_JSON)) {
464	                        isJsonResponse = true;
465	                        break;
466	                    }
467	                }
468	            }
469	            if (!isJsonResponse) {
470	                continue;
471	            }
472	
473	            ClassInfo effectiveReturnClassInfo = getEffectiveClassInfo(methodInfo.returnType(), indexView);
474	            if (effectiveReturnClassInfo == null) {
475	                continue;
476	            }
477	            AtomicBoolean needToDeleteCache = new AtomicBoolean(false);
478	            if (hasSecureFields(indexView, effectiveReturnClassInfo, typeToHasSecureField, needToDeleteCache)) {
479	                AnnotationInstance customSerializationAtClassAnnotation = methodInfo.declaringClass()
480	                        .declaredAnnotation(CUSTOM_SERIALIZATION);
481	                AnnotationInstance customSerializationAtMethodAnnotation = methodInfo.annotation(CUSTOM_SERIALIZATION);
482	                if (customSerializationAtMethodAnnotation != null || customSerializationAtClassAnnotation != null) {
483	                    log.warn("Secure serialization will not be applied to method: '" + methodInfo.declaringClass().name() + "#"
484	                            + methodInfo.name() + "' because the method or class are annotated with @CustomSerialization.");
485	                } else {
486	                    result.add(new ResourceMethodCustomSerializationBuildItem(methodInfo, entry.getActualClassInfo(),
487	                            SecurityCustomSerialization.class));
488	                }
489	            }
490	            if (needToDeleteCache.get()) {
491	                typeToHasSecureField.clear();
492	                typeToHasSecureField.putAll(getTypesWithSecureField());
493	            }
494	        }
495	        if (!result.isEmpty()) {
496	            for (ResourceMethodCustomSerializationBuildItem bi : result) {
497	                producer.produce(bi);
498	            }
499	        }
500	    }
