502	    private static ClassInfo getEffectiveClassInfo(Type type, IndexView indexView) {
503	        if (type.kind() == Type.Kind.VOID) {
504	            return null;
505	        }
506	        Type effectiveReturnType = getEffectiveType(type);
507	        return effectiveReturnType == null ? null : indexView.getClassByName(effectiveReturnType.name());
508	    }

